924: impl PendingSyncs {
925:     /// Locks the deferred sync queue.
926:     pub fn lock(&self) -> commonware_utils::sync::MappedMutexGuard<'_, Vec<DeferredSync>> {
927:         commonware_utils::sync::MutexGuard::map(self.state.lock(), |state| &mut state.syncs)
928:     }
