930:     /// Begins counting durability operations and blocks the next one behind a
931:     /// one-shot gate (pushed onto the deferred queue so tests can release it).
932:     ///
933:     /// Once the gate is consumed, started syncs park in the deferred queue as
934:     /// usual while [Self::calls] keeps counting.
935:     pub fn arm(&self) {
936:         let mut state = self.state.lock();
937:         assert!(!state.gate.tracking, "sync gate already armed");
938:         assert!(
939:             state.gate.waiter.is_none(),
940:             "sync gate already has a waiter"
941:         );
942:         state.gate.tracking = true;
943:         state.gate.calls = 0;
944:         let waiter = state.defer();
945:         state.gate.waiter = Some(waiter);
946:     }
947: 
948:     /// Returns the number of durability operations observed since [Self::arm].
949:     pub fn calls(&self) -> usize {
950:         self.state.lock().gate.calls
951:     }
952: 
953:     fn tracking(&self) -> bool {
954:         self.state.lock().gate.tracking
955:     }
