957:     /// Releases every parked sync and permanently stops parking new ones: future started syncs
958:     /// proceed immediately (or fail, after [Self::arm_fail]). Unlike [release_pending_syncs],
959:     /// which drains the queue once, this is sticky. A gate armed via [Self::arm] parks in the
960:     /// same queue, so this releases it too.
961:     pub fn unblock(&self) {
962:         let (drained, fail) = {
963:             let mut state = self.state.lock();
964:             state.unblocked = true;
965:             (mem::take(&mut state.syncs), state.fail)
966:         };
967:         for sync in drained {
968:             let result = if fail {
969:                 Err(injected_sync_failure())
970:             } else {
971:                 Ok(())
972:             };
973:             let _ = sync.release.send(result);
974:         }
975:     }
